using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;

namespace Cre8Labs.NetTools.Core.Oui
{
    /// <summary>
    /// MAC address to manufacturer, from the IEEE registry. The list is embedded as "oui.csv"
    /// ("AABBCC,Vendor" per line), generated by tools\update-oui.ps1.
    /// </summary>
    public static class OuiLookup
    {
        static readonly Lazy<Dictionary<string, string>> Table = new Lazy<Dictionary<string, string>>(LoadEmbedded);

        public static int Count => Table.Value.Count;

        /// <summary>The vendor for a MAC in any common format, or an empty string.</summary>
        public static string Vendor(string mac)
        {
            var hex = new string((mac ?? "").Where(Uri.IsHexDigit).ToArray()).ToUpperInvariant();
            if (hex.Length < 6) return "";
            // Locally administered MACs (randomised phones, virtual adapters) have no registered vendor.
            if ((Convert.ToByte(hex.Substring(0, 2), 16) & 0x02) != 0) return "";
            return Table.Value.TryGetValue(hex.Substring(0, 6), out var vendor) ? vendor : "";
        }

        /// <summary>Parses "AABBCC,Vendor" lines. Public so tests can check the format without the embedded file.</summary>
        public static Dictionary<string, string> Parse(TextReader reader)
        {
            var table = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                var comma = line.IndexOf(',');
                if (comma != 6) continue;
                var prefix = line.Substring(0, 6);
                if (!prefix.All(Uri.IsHexDigit)) continue;
                table[prefix.ToUpperInvariant()] = line.Substring(7).Trim();
            }
            return table;
        }

        static Dictionary<string, string> LoadEmbedded()
        {
            var assembly = Assembly.GetExecutingAssembly();
            var name = assembly.GetManifestResourceNames().FirstOrDefault(n => n.EndsWith("oui.csv", StringComparison.OrdinalIgnoreCase));
            if (name == null) return new Dictionary<string, string>();
            using (var stream = assembly.GetManifestResourceStream(name))
            using (var reader = new StreamReader(stream))
                return Parse(reader);
        }
    }
}
